$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent
$jobs=@{
 spear='First person JAVELIN throwing weapon animation. ONE dark shaft with small cyan steel spearhead. RIGHT hand ONLY grips rear third of shaft with overhand grip, thumb and fingers fully wrapped, right elbow pulled behind right shoulder, spear above shoulder at eye height, spearhead points FORWARD away from viewer toward upper center left. LEFT hand is open and forward for balance, NEVER grips shaft. Cells: 1 calm ready throw shoulder stance; 2 same ready stance; 3 pull elbow back; 4 maximum windup; 5 forward release spear; 6 empty right hand followthrough; 7 both hands empty waiting; 8 empty waiting; 9 empty waiting; 10 empty right hand reaching; 11 empty reaching; 12 catch returning shaft; 13 recover grip; 14 lift to shoulder; 15 ready shoulder stance; 16 same ready shoulder stance. NO swords shields guns duplicated spear or two handed polearm stance.'
 sword='First person SHIELD AND SHORT SABER warrior animation. Exactly ONE compact blue metal shield permanently strapped to LEFT forearm and gripped by LEFT hand. Exactly ONE short cyan steel saber gripped by RIGHT hand. Visible navy gloves white cuffs cyan wrist modules. Cells: 1 ready, shield low left, short blade low right; 2 right wrist draws back; 3 windup; 4 slash begins; 5 horizontal strike; 6 strike followthrough; 7 recover; 8 ready; 9 ready; 10 LEFT shield lifting; 11 shield rising; 12 shield almost raised; 13 FULL GUARD shield extremely close covers entire LEFT TWO THIRDS and central view, RIGHT sword only tiny sliver at BOTTOM RIGHT; 14 SAME full guard with small impact sparks on shield; 15 lower shield; 16 ready. Keep right sword far right in guard. Exactly two anatomically correct hands, one sword one shield in every frame, no floating shield, no extra weapons, NO gun NO spear NO full body.'
