 $prompt='Production FPS first person weapon sprite sheet. EXACTLY FOUR columns FOUR rows sixteen equal square cells, reading order, perfectly fixed camera and identical equipment scale across cells, coherent successive movement. Polished anime 3D cel shaded sci fi materials. '+$jobs[$name]+' Pure FLAT magenta #FF00FF background. No scenery no floor no shadows no captions no grid lines no text no watermark. Keep silhouettes inside individual cells; wrists may exit bottom edge. Empty upper left space except raised guard. Natural perspective from eyes of wearer, NOT side on third person inventory inspection.'
 & 'C:\Users\qiezh\.codex\skills\apinebula-imagegen\run.ps1' -Prompt $prompt -OutFile $target
 if(-not(Test-Path -LiteralPath $target)){throw $name}
}
